-- +goose StatementBegin
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM users
        WHERE name <> btrim(name)
           OR name <> normalize(name, NFKC)
           OR char_length(name) NOT BETWEEN 2 AND 24
           OR NOT danshi_valid_username_characters(name)
    ) THEN
        RAISE EXCEPTION
            'name 身份化前必须为所有既有用户补设 2–24 个字符且无首尾空白的 name'
            USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
        SELECT 1 FROM users GROUP BY lower(name) HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION
            'name 身份化前必须消除大小写不敏感的重复 name'
            USING ERRCODE = 'unique_violation';
    END IF;
END;
$$;
-- +goose StatementEnd

ALTER TABLE users
    ADD CONSTRAINT users_name_identity_check CHECK (
        name = btrim(name)
        AND name = normalize(name, NFKC)
        AND char_length(name) BETWEEN 2 AND 24
        AND danshi_valid_username_characters(name)
    );

CREATE UNIQUE INDEX uq_users_name_lower ON users (lower(normalize(name, NFKC)));

CREATE TABLE user_name_claims (
    id         bigint       PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    user_id    bigint       NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
    name       varchar(24) NOT NULL,
    created_at timestamptz  NOT NULL DEFAULT now(),

    CONSTRAINT user_name_claims_name_check CHECK (
        name = btrim(name)
        AND name = normalize(name, NFKC)
        AND char_length(name) BETWEEN 2 AND 24
        AND danshi_valid_username_characters(name)
    )
);

CREATE UNIQUE INDEX uq_user_name_claims_name_lower
    ON user_name_claims (lower(normalize(name, NFKC)));
CREATE INDEX idx_user_name_claims_user ON user_name_claims (user_id, created_at DESC);

INSERT INTO user_name_claims (user_id, name, created_at)
SELECT id, name, created_at FROM users;

-- 夹具、导入与运维脚本同样可能直接写 users。触发器把“当前 name 必须有归属记录、
-- 旧 name 不可被另一账号接管”落实为数据库防线；应用层仍先显式 ClaimUsername，以便将
-- 冲突转换为稳定业务错误而不是依赖触发器文案。
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION danshi_claim_user_name()
RETURNS trigger
LANGUAGE plpgsql
AS $func$
DECLARE
    owner_id bigint;
    inserted integer;
BEGIN
    INSERT INTO user_name_claims (user_id, name, created_at)
    VALUES (NEW.id, NEW.name, NEW.created_at)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted = 1 THEN
        RETURN NEW;
    END IF;

    SELECT user_id INTO owner_id
    FROM user_name_claims
    WHERE lower(normalize(name, NFKC)) = lower(normalize(NEW.name, NFKC));
    IF owner_id IS DISTINCT FROM NEW.id THEN
        RAISE EXCEPTION 'name 已被其他账号占用'
            USING ERRCODE = 'unique_violation', CONSTRAINT = 'uq_user_name_claims_name_lower';
    END IF;
    RETURN NEW;
END;
$func$;
-- +goose StatementEnd

CREATE TRIGGER trg_users_claim_name
    AFTER INSERT OR UPDATE OF name ON users
    FOR EACH ROW EXECUTE FUNCTION danshi_claim_user_name();

CREATE TRIGGER trg_user_name_claims_forbid_update
    BEFORE UPDATE ON user_name_claims
    FOR EACH ROW EXECUTE FUNCTION danshi_forbid_row_update();

CREATE TRIGGER trg_user_name_claims_forbid_delete
    BEFORE DELETE ON user_name_claims
    FOR EACH ROW EXECUTE FUNCTION danshi_forbid_hard_delete();

COMMENT ON TABLE user_name_claims IS
    '用户名的追加占用记录。users.name 保存当前用户名；所有历史用户名永久保留，防止改名或注销后身份被冒用。';

COMMENT ON COLUMN users.name IS '唯一、可登录的公开用户名；应用字段为 username，规范化后 2–24 个字符；历史名称永久归原账号占用。';
COMMENT ON COLUMN user_name_claims.name IS '当前或历史用户名；大小写不敏感的唯一归属，改名和注销不释放。';
COMMENT ON COLUMN moderation_records.field IS '被审的具体字段。用户对象必填（name 用户名 / bio 简介）；用户名审核通过后才写入。帖子可用 title / content 区分，整体送审时留空。评论、标签、图片各自只有一个可审内容，无需本列。';

-- +goose Down

COMMENT ON COLUMN users.name IS '展示昵称，非唯一。空串表示未设置（非 NULL，简化前端处理）。';
COMMENT ON COLUMN moderation_records.field IS '被审的具体字段。用户对象必填（name 昵称 / bio 简介）；帖子可用 title / content 区分，整体送审时留空。评论、标签、图片各自只有一个可审内容，无需本列。';

DROP TRIGGER IF EXISTS trg_user_name_claims_forbid_delete ON user_name_claims;
DROP TRIGGER IF EXISTS trg_user_name_claims_forbid_update ON user_name_claims;
DROP TRIGGER IF EXISTS trg_users_claim_name ON users;
DROP FUNCTION IF EXISTS danshi_claim_user_name();
DROP TABLE IF EXISTS user_name_claims;
DROP INDEX IF EXISTS uq_users_name_lower;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_name_identity_check;

DROP FUNCTION IF EXISTS danshi_valid_username_characters(text);
